const syncDefaultIssueLifecycleStatuses = `-- name: SyncDefaultIssueLifecycleStatuses :exec
INSERT INTO issue_lifecycle_status (
    workspace_id, lifecycle_id, legacy_status_key, name, description, color,
    position, phase, outcome, archived_at, created_at, updated_at
)
SELECT
    s.workspace_id,
    $1::uuid,
    s.key,
    s.name,
    s.description,
    s.color,
    s.position,
    CASE s.category
        WHEN 'backlog' THEN 'backlog'
        WHEN 'todo' THEN 'unstarted'
        WHEN 'done' THEN 'completed'
        WHEN 'cancelled' THEN 'cancelled'
        ELSE 'started'
    END,
    CASE s.category
        WHEN 'done' THEN 'completed'
        WHEN 'cancelled' THEN 'cancelled'
        ELSE NULL
    END,
    s.archived_at,
    s.created_at,
    s.updated_at
FROM issue_status AS s
WHERE s.workspace_id = $2::uuid
ON CONFLICT (lifecycle_id, legacy_status_key) WHERE legacy_status_key IS NOT NULL
DO UPDATE SET
    name = EXCLUDED.name,
    description = EXCLUDED.description,
    color = EXCLUDED.color,
    position = EXCLUDED.position,
    phase = EXCLUDED.phase,
    outcome = EXCLUDED.outcome,
    archived_at = EXCLUDED.archived_at,
    updated_at = EXCLUDED.updated_at
`

type SyncDefaultIssueLifecycleStatusesParams struct {
	LifecycleID pgtype.UUID `json:"lifecycle_id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

func (q *Queries) SyncDefaultIssueLifecycleStatuses(ctx context.Context, arg SyncDefaultIssueLifecycleStatusesParams) error {
	_, err := q.db.Exec(ctx, syncDefaultIssueLifecycleStatuses, arg.LifecycleID, arg.WorkspaceID)
	return err
}

